"use client";

import Image from "next/image";
import { useParams, useRouter } from "next/navigation";
import { useEffect, useState } from "react";

import ImageUploadField from "@/components/ImageUploadField/page";
import { useUser } from "@/context/UserContext";
import type { AuthenticatedUser } from "@/hooks/useAuth";
import { graphqlRequest } from "@/lib/graphql";
import type { UploadedMedia } from "@/lib/upload";
import styles from "./profile.module.css";

type Profile = Omit<AuthenticatedUser, "email"> & { email?: string | null };
const FIELDS = "id name username email profilePicture accountType subscription { plan status autoRenew }";

export default function ProfilePage() {
  const { username } = useParams<{ username: string }>();
  const router = useRouter();
  const { authenticatedUser, authToken, authLoading, updateAuthenticatedUser } = useUser();
  const [profile, setProfile] = useState<Profile | null>(null);
  const [name, setName] = useState("");
  const [media, setMedia] = useState<UploadedMedia | null>(null);
  const [busy, setBusy] = useState(false);
  const [message, setMessage] = useState("");
  const ownProfile = authenticatedUser?.username === username;

  useEffect(() => {
    graphqlRequest<{ user: Profile | null }>(
      `query($username:String!){user(username:$username){${FIELDS}}}`,
      { username },
      authToken,
    ).then(({ user }) => {
      setProfile(user);
      setName(user?.name ?? "");
    }).catch((error: Error) => setMessage(error.message));
  }, [username, authToken]);

  if (authLoading || !profile) {
    return <main className={styles.page}><p>{message || "Carregando perfil…"}</p></main>;
  }

  async function save() {
    if (!profile) return;
    setBusy(true);
    setMessage("");
    try {
      const { updateMyProfile } = await graphqlRequest<{ updateMyProfile: AuthenticatedUser }>(
        `mutation($data:UpdateProfileInput!){updateMyProfile(data:$data){${FIELDS}}}`,
        { data: { name, ...(media ? { profilePictureID: media.id } : {}) } },
        authToken,
      );
      setProfile(updateMyProfile);
      updateAuthenticatedUser(updateMyProfile);
      setMedia(null);
      setMessage("Perfil atualizado.");
      router.refresh();
    } catch (error) {
      setMessage(error instanceof Error ? error.message : "Falha ao salvar.");
    } finally {
      setBusy(false);
    }
  }

  return (
    <main className={styles.page}>
      <section className={styles.card}>
        <div className={styles.header}>
          <Image src={profile.profilePicture || "/image-placeholder.svg"} alt="Foto de perfil" width={112} height={112} unoptimized />
          <div><h1>{profile.name}</h1><p>@{profile.username}</p><span>{profile.subscription.plan}</span></div>
        </div>
        {ownProfile && (
          <div className={styles.form}>
            <ImageUploadField label="Foto de perfil" purpose="USER_AVATAR" shape="circle" currentUrl={profile.profilePicture} value={media} onChange={setMedia} disabled={busy} />
            <label>Nome<input value={name} maxLength={120} onChange={(event) => setName(event.target.value)} /></label>
            <label>E-mail<input value={profile.email ?? ""} disabled /></label>
            <button onClick={() => void save()} disabled={busy || name.trim().length < 2}>{busy ? "Salvando…" : "Salvar alterações"}</button>
            {message && <p>{message}</p>}
          </div>
        )}
      </section>
    </main>
  );
}
